struct ActiveVoice {
    sink: rodio::Sink,
    looping: bool,
}

impl ActiveVoice {
    fn is_naturally_complete(&self) -> bool {
        managed_voice_naturally_completes(self.looping, self.sink.empty())
    }
}

fn managed_voice_naturally_completes(looping: bool, sink_empty: bool) -> bool {
    !looping && sink_empty
}
